-- Architecture section 7. Change additively only. JSON columns hold text; ids are content hashes unless noted.
CREATE TABLE IF NOT EXISTS run (run_id TEXT PRIMARY KEY, started_at TEXT NOT NULL, as_of TEXT NOT NULL, profile TEXT NOT NULL CHECK (profile IN ('replay','demo','aws','self-hosted')), seed INTEGER NOT NULL, batch TEXT NOT NULL CHECK (batch IN ('all','sep','oct')), data_hash TEXT NOT NULL, config_hash TEXT NOT NULL, prompt_versions TEXT NOT NULL, model_ids TEXT NOT NULL, output_hash TEXT, cost_usd REAL NOT NULL DEFAULT 0, status TEXT NOT NULL CHECK (status IN ('running','done','failed')), manifest_json TEXT);
CREATE TABLE IF NOT EXISTS account (account_id TEXT PRIMARY KEY, name TEXT NOT NULL, arr_gbp REAL, tier TEXT, renewal_date TEXT);
CREATE TABLE IF NOT EXISTS raw_record (raw_id TEXT PRIMARY KEY, source TEXT NOT NULL CHECK (source IN ('gong','intercom','fireflies','fullstory','hubspot','shortcut','notion')), route TEXT CHECK (route IS NULL OR route IN ('sales','support','onboarding','account_management','sessions')), source_id TEXT NOT NULL, account_id TEXT, account_status TEXT CHECK (account_status IS NULL OR account_status IN ('resolved','unresolved','ambiguous')), occurred_at TEXT, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS snippet (snippet_id TEXT PRIMARY KEY, raw_id TEXT NOT NULL, speaker_email TEXT, text TEXT NOT NULL, context_text TEXT, start_ms INTEGER, end_ms INTEGER);
CREATE TABLE IF NOT EXISTS triage (snippet_id TEXT NOT NULL, run_id TEXT NOT NULL, call_id TEXT, backend TEXT NOT NULL, is_signal_p REAL, bucket TEXT, bucket_conf REAL, severity INTEGER, signal_type TEXT, decision TEXT NOT NULL CHECK (decision IN ('keep','drop','low_confidence','untriaged')), latency_ms REAL, audit_weight REAL, PRIMARY KEY (snippet_id, run_id));
CREATE TABLE IF NOT EXISTS insight (insight_id TEXT PRIMARY KEY, snippet_id TEXT NOT NULL, run_id TEXT NOT NULL, call_id TEXT, problem TEXT NOT NULL, quote TEXT NOT NULL, quote_match TEXT NOT NULL CHECK (quote_match IN ('exact','normalised','failed')), quote_span_start INTEGER, quote_span_end INTEGER, workflow TEXT, desired_outcome TEXT, severity INTEGER NOT NULL CHECK (severity BETWEEN 1 AND 4), account_id TEXT, account_status TEXT, embedding TEXT);
CREATE TABLE IF NOT EXISTS opportunity (opportunity_id TEXT PRIMARY KEY, title TEXT NOT NULL, problem_statement TEXT NOT NULL, bucket TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('new','proposed','accepted','merged','rejected','parked','intent_drafted','in_factory','shipped','enabled','measured')), squad TEXT, first_seen_as_of TEXT NOT NULL, centroid TEXT, merged_into TEXT, tag TEXT NOT NULL DEFAULT 'none' CHECK (tag IN ('none','shipped','on_roadmap')), tag_ref TEXT, tag_state TEXT CHECK (tag_state IS NULL OR tag_state IN ('proposed','confirmed','removed')));
CREATE TABLE IF NOT EXISTS opportunity_insight (opportunity_id TEXT NOT NULL, insight_id TEXT NOT NULL, similarity REAL NOT NULL, post_ship INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (opportunity_id, insight_id));
CREATE TABLE IF NOT EXISTS score (opportunity_id TEXT NOT NULL, run_id TEXT NOT NULL, total REAL NOT NULL, breadth REAL NOT NULL, severity REAL NOT NULL, value REAL NOT NULL, corroboration REAL NOT NULL, recency REAL NOT NULL, renewal REAL NOT NULL, roadmap REAL NOT NULL, unresolved_insights INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (opportunity_id, run_id));
CREATE TABLE IF NOT EXISTS brief (brief_id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL, run_id TEXT NOT NULL, call_id TEXT, body_md TEXT NOT NULL, citations_json TEXT NOT NULL, check_status TEXT NOT NULL CHECK (check_status IN ('passed','failed_checks')), check_failures_json TEXT NOT NULL DEFAULT '[]', prompt_version TEXT NOT NULL, model TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS judge_version (judge_version_id TEXT PRIMARY KEY, judge TEXT NOT NULL CHECK (judge IN ('faithfulness','signal','duplicate')), prompt_version TEXT NOT NULL, model TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('uncalibrated','calibrating','trusted','revoked')), n_pass INTEGER NOT NULL DEFAULT 0, n_fail INTEGER NOT NULL DEFAULT 0, tpr REAL, tnr REAL, tpr_lower REAL, tnr_lower REAL, state_changed_at TEXT);
CREATE TABLE IF NOT EXISTS judgement (judgement_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, call_id TEXT, judge_version_id TEXT NOT NULL, judge TEXT NOT NULL CHECK (judge IN ('faithfulness','signal','duplicate')), target_type TEXT NOT NULL CHECK (target_type IN ('brief','opportunity')), target_id TEXT NOT NULL, verdict TEXT NOT NULL CHECK (verdict IN ('pass','fail')), critique TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS annotation (annotation_id TEXT PRIMARY KEY, target_type TEXT NOT NULL, target_id TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL CHECK (action IN ('accept','merge','split','reject','park','reassign','edit','undo','confirm_tag','remove_tag')), reason_code TEXT CHECK (reason_code IS NULL OR reason_code IN ('not_product_signal','already_shipped','already_on_roadmap','evidence_wrong','mixed_problems','low_value','other')), note TEXT, undo_of TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS label (label_id TEXT PRIMARY KEY, judge TEXT NOT NULL CHECK (judge IN ('faithfulness','signal','duplicate')), target_type TEXT NOT NULL, target_id TEXT NOT NULL, verdict TEXT NOT NULL CHECK (verdict IN ('pass','fail')), critique TEXT, origin TEXT NOT NULL CHECK (origin IN ('real_pm','synthetic_seed','live_reviewer')), blind INTEGER NOT NULL, split TEXT NOT NULL CHECK (split IN ('dev','held_out')), weight REAL NOT NULL DEFAULT 1, actor TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS handoff (handoff_id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL, intent_doc_md TEXT, factory_job_json TEXT, evidence_snapshot TEXT NOT NULL DEFAULT '[]', manifest_hash TEXT, status TEXT NOT NULL CHECK (status IN ('drafted','approved','sent','rejected_by_factory','superseded','cancelled')), factory_reason TEXT, errors_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS outtake (outtake_id TEXT PRIMARY KEY, story_ref TEXT NOT NULL, call_id TEXT, kind TEXT NOT NULL CHECK (kind IN ('release_note','help_article','change_notice','followup_brief')), body_md TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('draft','accepted','rejected')));
CREATE TABLE IF NOT EXISTS model_call (call_id TEXT PRIMARY KEY, run_id TEXT, stage TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, model TEXT NOT NULL, profile TEXT NOT NULL, endpoint TEXT, prompt_version TEXT, input_hash TEXT NOT NULL, output_hash TEXT NOT NULL, tokens_in INTEGER NOT NULL DEFAULT 0, tokens_out INTEGER NOT NULL DEFAULT 0, cost_usd REAL NOT NULL DEFAULT 0, latency_ms REAL NOT NULL DEFAULT 0, cached INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_event (event_id TEXT PRIMARY KEY, at TEXT NOT NULL, actor TEXT NOT NULL, actor_kind TEXT NOT NULL CHECK (actor_kind IN ('system','person')), action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, details_json TEXT NOT NULL, prev_hash TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS audit_no_replace BEFORE INSERT ON audit_event WHEN EXISTS (SELECT 1 FROM audit_event WHERE event_id=NEW.event_id) BEGIN SELECT RAISE(ABORT, 'audit_event is append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit_event BEGIN SELECT RAISE(ABORT, 'audit_event is append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit_event BEGIN SELECT RAISE(ABORT, 'audit_event is append-only'); END;
